document.querySelectorAll('.mobile-controls button').forEach(b=>b.addEventListener('pointerdown',e=>{e.preventDefault();const d=b.dataset.dir;if(d==='up')movePlayer(0,-8);if(d==='down')movePlayer(0,8);if(d==='left')movePlayer(-8,0);if(d==='right')movePlayer(8,0)}));
$('soundBtn').addEventListener('click',()=>{$('soundBtn').textContent=state.sound?'♫ SONIDO: OFF':'♫ SONIDO: ON';state.sound=!state.sound;if(state.sound)log('Sonido ambiental activado (prototipo visual).')});
// Responsive hit area keeps the target grid aligned exactly with the arena.
setPhase('idle');$('enemySoul').classList.remove('hidden');$('soulLabel').classList.remove('hidden');
log('El Vigía emerge de la penumbra.');log('Tu alma late. Hay dos acciones disponibles.');
