$('endBtn').onclick=()=>{if(s.phase==='player')enemyTurn()};
function execute(){if(s.mode!=='select'||!s.skill)return;let k=s.skill;s.actions--;phase('resolve');let coords=k.mode==='random'?Array.from({length:k.count},()=>({x:Math.floor(Math.random()*6),y:Math.floor(Math.random()*4)})):k.mode==='seek'?[{x:Math.max(0,Math.min(5,Math.floor(s.x/100*6))),y:Math.max(0,Math.min(3,Math.floor(s.y/100*4)))}]:s.zones.slice();coords.forEach((p,i)=>setTimeout(()=>hit(k,p),i*90));let dmg=k.damage*((k.mode==='row'||k.mode==='col')?1:coords.length);setTimeout(()=>{s.ehp=Math.max(0,s.ehp-dmg);info();toast(`−${dmg} RESISTENCIA`,k.name);log(`${k.name} impacta ${coords.length===1?'una zona':coords.length+' zonas'} (${dmg} de daño).`);s.skill=null;s.zones=[];if(s.ehp<=0){phase('idle');finish(true)}else if(s.actions<=0)setTimeout(enemyTurn,700);else{phase('idle');$('arenaStatus').textContent=`Impacto confirmado. Quedan ${s.actions} acción(es) o finaliza el turno.`;$('skillHint').textContent='Elige otra técnica o pulsa FINALIZAR TURNO.'}},650+coords.length*90)}
